'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{spawn}=require('node:child_process');
const root=path.resolve(__dirname,'..'),project=path.resolve(root,'../.rural-quiz-runtime/theme-content-review'),out=path.join(root,'qa/audio-settings-20261020');fs.mkdirSync(out,{recursive:true});const events=[],checks=[];
async function call(tool,args=[]){return new Promise((resolve,reject)=>{const c=spawn('/usr/local/bin/wechatide',['-c','Codex',tool,'--project',project,...args]);let s='';c.stdout.on('data',b=>s+=b);c.stderr.on('data',b=>s+=b);const t=setTimeout(()=>{c.kill();reject(Error(tool+' timeout'));},45000);c.on('close',code=>{clearTimeout(t);let r;try{r=JSON.parse(s.slice(s.indexOf('{')));}catch{return reject(Error(s.slice(0,1000)));}events.push({tool,args,result:r});fs.writeFileSync(path.join(out,'native-events.json'),JSON.stringify(events,null,2));if(code||!r.ok||r.result?.success===false)return reject(Error(r.message||r.result?.error));resolve(r.result);});});}
const tap=s=>call('automation_element_action',['--action','tap','--selector',s,'--wait-for-selector',s]);
const change=(s,value)=>call('automation_element_action',['--action','trigger','--selector',s,'--type','change','--detail',JSON.stringify({value}),'--wait-for-selector',s]);
async function data(){return(await call('automation_page_action',['--action','getData','--wait-for-selector','.game-device'])).data;}
function record(name,d){checks.push({name,passed:true,state:{open:d.soundSettingsOpen,musicEnabled:d.musicEnabled,effectsEnabled:d.effectsEnabled,musicVolume:d.musicVolume,effectsVolume:d.effectsVolume,musicPlaying:d.soundPlaying,effectPlays:d.soundEffectPlays,lastEffect:d.lastSoundEffect}});console.log('PASS '+name);}
(async()=>{let d=await data();if(!d.soundSettingsOpen)await tap('#sound-settings');await change('#music-switch',false);await change('#effects-switch',true);d=await data();assert.equal(d.musicEnabled,false);assert.equal(d.effectsEnabled,true);assert.equal(d.soundPlaying,false);record('music off leaves effects enabled',d);
 await change('#effects-volume',75);d=await data();assert.equal(d.effectsVolume,75);assert.equal(d.lastSoundEffect,'select');record('effect slider commits and previews the natural cue',d);
 await change('#music-volume',25);d=await data();assert.equal(d.musicVolume,25);assert.equal(d.musicEnabled,true);assert.equal(d.soundPlaying,true);record('music slider restores music at its own level',d);
 await tap('#sound-master');d=await data();assert.equal(d.soundEnabled,false);assert.equal(d.soundPlaying,false);record('one tap mutes both channels',d);
 await tap('#sound-master');d=await data();assert.equal(d.musicVolume,25);assert.equal(d.effectsVolume,75);assert.equal(d.musicEnabled,true);assert.equal(d.effectsEnabled,true);record('restore keeps independent levels',d);
 await tap('#sound-settings-done');d=await data();assert.equal(d.soundSettingsOpen,false);await tap('#sound-settings');d=await data();assert.equal(d.musicVolume,25);assert.equal(d.effectsVolume,75);record('close and reopen retain settings',d);
 const stored=await call('automation_evaluate',['--fn-source','function(){return wx.getStorageSync("rural-quiz:audio:settings-v1");}']);let s=stored;for(let i=0;i<4&&!s.version;i++)s=s.result||s.data||s;assert.equal(s.musicLevel,.25);assert.equal(s.effectsLevel,.75);record('native preference storage contains committed levels',d);
 // Leave this disposable fixture at the agreed default mix after checking changed levels.
 await change('#music-volume',40);await change('#effects-volume',60);await tap('#sound-settings-done');
 fs.writeFileSync(path.join(out,'native-interactions.json'),JSON.stringify({passed:true,scope:'Native WXML controls and Page event bindings in an isolated review project. Slider/switch change events are delivered by the native automator; not physical phone gestures or audible listening.',checks},null,2)+'\n');
})().catch(e=>{fs.writeFileSync(path.join(out,'native-interactions.json'),JSON.stringify({passed:false,checks,error:e.stack},null,2)+'\n');console.error(e);process.exitCode=1;});
